# Illustrative example, spec version 2026-08-25.
POST /ucp/v1/checkout-sessions HTTP/1.1
Host: shop.example
UCP-Agent: profile="https://agent.example/profiles/shopping-agent.json"

# MCP form of the same advertisement
{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "params": {
    "name": "create_checkout",
    "arguments": {
      "meta": {
        "ucp-agent": {
          "profile": "https://agent.example/profiles/shopping-agent.json"
        }
      },
      "checkout": {
        "line_items": []
      }
    }
  },
  "id": 1
}

// Illustrative example, spec version 2026-08-25. Platform profile, abbreviated.
{
  "ucp": {
    "version": "2026-08-25",
    "capabilities": {
      "dev.ucp.shopping.checkout": [
        {
          "version": "2026-08-25"
        }
      ],
      "dev.ucp.shopping.fulfillment": [
        {
          "version": "2026-08-25",
          "extends": "dev.ucp.shopping.checkout"
        }
      ],
      "dev.ucp.shopping.cart": [
        {
          "version": "2026-08-25"
        }
      ]
    }
  }
}

// Illustrative example, spec version 2026-08-25. Abbreviated: the required payment_handlers map is omitted.
{
  "ucp": {
    "version": "2026-08-25",
    "status": "success",
    "capabilities": {
      "dev.ucp.shopping.checkout": [
        {
          "version": "2026-08-25"
        }
      ],
      "dev.ucp.shopping.fulfillment": [
        {
          "version": "2026-08-25"
        }
      ]
    }
  }
}
